package com.agriconnect.order;import java.math.*;import java.time.*;import java.util.*;import org.springframework.http.*;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.jdbc.support.GeneratedKeyHolder;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/crop-locks")class CropLockController{private final JdbcClient db;private final CropInventoryClient crop;CropLockController(JdbcClient d,CropInventoryClient c){db=d;crop=c;}private long uid(){return Long.parseLong(SecurityContextHolder.getContext().getAuthentication().getName());}private String sel(){return"select id,batch_id as \"batchId\",buyer_id as \"buyerId\",quantity,status,locked_at as \"lockedAt\",expired_at as \"expiredAt\",inventory_reservation_id as \"inventoryReservationId\" from crop_locks";}
@GetMapping List<Map<String,Object>>all(@RequestParam(required=false)Long batchId,@RequestParam(required=false)Long buyerId,@RequestParam(required=false)String status){var a=SecurityContextHolder.getContext().getAuthentication();boolean admin=a.getAuthorities().stream().anyMatch(x->Set.of("ROLE_ADMIN","ROLE_LOGISTICS").contains(x.getAuthority()));Long effectiveBuyerId=admin?buyerId:uid();return db.sql(sel()+" where (:b is null or batch_id=:b) and (:u is null or buyer_id=:u) and (:st is null or status=:st) order by id desc").param("b",batchId).param("u",effectiveBuyerId).param("st",status).query().listOfRows();}
@PostMapping @PreAuthorize("hasRole('BUYER')")ResponseEntity<?>create(@RequestHeader("Idempotency-Key")String key,@RequestBody Map<String,Object>x){long batch=((Number)x.get("batchId")).longValue();BigDecimal q=new BigDecimal(String.valueOf(x.get("quantity")));Instant exp=x.get("expiredAt")==null?Instant.now().plusSeconds(900):Instant.parse(String.valueOf(x.get("expiredAt")));UUID request=UUID.nameUUIDFromBytes((uid()+":lock:"+key).getBytes());Map<String,Object>r=crop.reserve(request,"LOCK-"+key,batch,uid(),q,exp);UUID rid=UUID.fromString(String.valueOf(r.get("reservationId")));var existing=db.sql(sel()+" where inventory_reservation_id=:r").param("r",rid).query().listOfRows().stream().findFirst();if(existing.isPresent())return ResponseEntity.ok(existing.get());var kh=new GeneratedKeyHolder();db.sql("insert into crop_locks(inventory_reservation_id,batch_id,buyer_id,quantity,status,expired_at)values(:r,:b,:u,:q,'ACTIVE',:e)").param("r",rid).param("b",batch).param("u",uid()).param("q",q).param("e",exp).update(kh,"id");return ResponseEntity.status(201).body(one(kh.getKey().longValue()));}
@GetMapping("/{id}")Map<String,Object>one(@PathVariable long id){var x=db.sql(sel()+" where id=:id").param("id",id).query().listOfRows().stream().findFirst().orElseThrow(()->new DomainException(HttpStatus.NOT_FOUND,"CROP_LOCK_NOT_FOUND","Crop lock not found"));var a=SecurityContextHolder.getContext().getAuthentication();boolean admin=a.getAuthorities().stream().anyMatch(y->Set.of("ROLE_ADMIN","ROLE_LOGISTICS").contains(y.getAuthority()));if(!admin&&((Number)x.get("buyerId")).longValue()!=uid())throw new DomainException(HttpStatus.FORBIDDEN,"FORBIDDEN","Crop lock is not owned by this buyer");return x;}
@DeleteMapping("/{id}")@PreAuthorize("hasRole('BUYER')")ResponseEntity<Void>delete(@PathVariable long id){Map<String,Object>x=one(id);if("ACTIVE".equals(x.get("status"))){crop.release(UUID.fromString(String.valueOf(x.get("inventoryReservationId"))));db.sql("update crop_locks set status='EXPIRED' where id=:id and status='ACTIVE'").param("id",id).update();}return ResponseEntity.noContent().build();}}
